SCOPES = {'penn-state-ai-engineering-bs': ['A-I 100', 'A-I 305', 'A-I 341W', 'A-I 370', 'A-I 375', 'A-I 410', 'AIE 355', 'AIE 489W', 'CAS 100A', 'CAS 100B', 'CAS 138T', 'CMPSC 121', 'CMPSC 122', 'CMPSC 131', 'CMPSC 132', 'CMPSC 360', 'CMPSC 445', 'CMPSC 448', 'DS 120', 'EE 456', 'ENGL 137H', 'ENGL 15', 'ENGL 202C', 'ENGL 30H', 'MATH 140', 'MATH 141', 'MATH 225', 'PHYS 211', 'PHYS 212', 'STAT 401'], 'penn-state-ai-methods-applications-ist-bs': ['A-I 100', 'A-I 341W', 'A-I 370', 'A-I 375', 'A-I 494', 'AIMA 430', 'AIMA 440', 'CMPSC 131', 'CMPSC 132', 'CMPSC 360', 'CMPSC 445', 'CMPSC 448', 'CMPSC 462', 'CMPSC 465', 'DS 200', 'DS 305', 'DS 310', 'EE 456', 'MATH 140', 'MATH 225', 'MATH 311W', 'STAT 200', 'STAT 401', 'DS 410', 'CMPSC 410', 'DS 442', 'CMPSC 442', 'MATH 318', 'STAT 318', 'MATH 414', 'STAT 414']}

def parse_courses(html,pid,prefix):
 soup=BeautifulSoup(html,'html.parser');wanted={c for c in SCOPES[pid] if c.split()[0].lower()==prefix};out=[]
 for block in soup.select('.courseblock'):
  title=block.select_one('.courseblocktitle .course_codetitle')
  if title is None:continue
  parts=clean(title.get_text(' ',strip=True)).split(': ',1)
  if len(parts)!=2 or parts[0] not in wanted:continue
  code,name=parts;text=clean(block.get_text(' ',strip=True));reviewed=SPEC[code]
  if hashlib.sha256(text.encode()).hexdigest()!=reviewed['digest']:raise ValueError('Penn State course block changed; review required: '+code)
  raw=clean(block.select_one('.courseblocktitle .course_credits').get_text(' ',strip=True));m=re.fullmatch(r'(\d+) Credits?',raw)
  c=course('psu',code,name,pid+'-courses-'+prefix,'https://bulletins.psu.edu/university-course-descriptions/undergraduate/'+prefix+'/',credits=int(m[1]) if m else None,unit='semester_hours',category=reviewed['category'])
  c['description']=reviewed['description'];clauses=[]
  for extra in block.select('.courseblockextra p'):
   value=clean(extra.get_text(' ',strip=True))
   if any(x in value for x in ['Prerequisite','Concurrent','Recommended Preparation']):clauses.append(value)
  c['prerequisites']=' '.join(clauses) or None;out.append(c)
 if {c['code'] for c in out}!=wanted:raise ValueError('Reviewed Penn State core identities missing')
 return {'id':pid,'courses':out}

def source_parsers(pid):
 return {'https://bulletins.psu.edu/university-course-descriptions/undergraduate/'+prefix+'/':partial(parse_courses,pid=pid,prefix=prefix) for prefix in sorted({c.split()[0].lower() for c in SCOPES[pid]})}
